SELECT id, name, email, city, is_active, age, LEAD(credit_limit) OVER (PARTITION BY country ORDER BY signup_date, id) AS next_credit_limit, LAG(age) OVER (PARTITION BY country ORDER BY signup_date, id) AS prev_age, LEAD(age) OVER (PARTITION BY country ORDER BY signup_date, id) AS next_age, ROW_NUMBER() OVER (PARTITION BY country ORDER BY signup_date, id) AS seq_no FROM customers WHERE city IS NOT NULL
